/** Re-trim live items to the current budget (turn start shrinks the budget
 * to make room for the stream/thought area). */
const trimLive = useCallback(() => {
  let live = [...liveRef.current];
  const budget = liveBudget(runningRef.current);
  const flushed: Item[] = [];
  let total = live.reduce((a, it) => a + estimateRows(it), 0);
  while (total > budget && live.length > 0) {
    const old = live.shift()!;
    if (!old.tailOnly) flushed.push(old);
    total -= estimateRows(old);
  }
  if (flushed.length > 0) {
    staticRef.current = [...staticRef.current, ...flushed];
    setStaticItems(staticRef.current);
  }
  liveRef.current = live;
  setLiveItems(live);
}, [estimateRows, liveBudget]);
